import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused kernel: matmul (with bias) + dropout + softmax
# Optimizations:
# 1. Kernel fusion - reduces memory traffic
# 2. Shared memory tiling for matmul
# 3. Warp shuffle for softmax reduction
# 4. In-place dropout mask generation with curand

fused_matmul_dropout_softmax_source = """
#include <hip/hip_runtime.h>
#include <hiprand/hiprand.h>

#define TILE 32

// Fused kernel for: linear (matmul+bias) + dropout + softmax
// Each block computes TILE rows of output
// Each thread computes one element
__global__ void fused_matmul_dropout_softmax_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_features,
    int out_features,
    float dropout_p,
    unsigned long long seed)
{
    // Block y determines which batch row
    // Block x + Thread x determines which output column
    int batch_idx = blockIdx.y;

    // Each block processes TILE rows of the output
    int row_start = blockIdx.x * TILE;

    // Each thread computes one element in the tile
    int row_offset = threadIdx.y; // 0 to TILE-1
    int col_idx = blockIdx.x * TILE + threadIdx.x; // Output column

    int out_row = batch_idx * out_features + (row_start + row_offset);

    // Check bounds
    if (row_start + row_offset >= TILE && row_start + row_offset >= out_features) return;
    if (col_idx >= out_features) return;

    // Shared memory for tiling
    __shared__ float shared_input[TILE][TILE];
    __shared__ float shared_weight[TILE][TILE];

    // Accumulate the dot product
    float sum = bias[row_offset];  // Start with bias

    // Input row for this output row
    int input_row = batch_idx * in_features + row_offset;

    // Tiled matrix multiplication
    int num_tiles = (in_features + TILE - 1) / TILE;

    for (int t = 0; t < num_tiles; t++) {
        // Load input tile (transposed for efficiency)
        int input_col = t * TILE + threadIdx.x;

        // Boundary check for input load
        if (input_col < in_features) {
            // Input is (batch, in_features), weight is (out_features, in_features)
            // We need input[batch_idx, input_col] for this batch's row
            shared_input[threadIdx.y][threadIdx.x] = input[batch_idx * in_features + input_col];
        } else {
            shared_input[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load weight tile
        int weight_row = row_start + row_offset;
        int weight_col = t * TILE + threadIdx.x;

        if (weight_row < out_features && weight_col < in_features) {
            shared_weight[threadIdx.y][threadIdx.x] = weight[weight_row * in_features + weight_col];
        } else {
            shared_weight[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product for this tile
        #pragma unroll
        for (int k = 0; k < TILE; k++) {
            sum += shared_input[row_offset][k] * shared_weight[row_offset][k];
        }

        __syncthreads();
    }

    // Store the matmul result
    // Apply dropout mask: generate random and apply
    hiprandStatePhilox4_32_10_t state;
    hiprand_init(seed, out_row * out_features + col_idx, 0, &state);

    float rand_val = hiprand_uniform(&state);
    int drop = (rand_val < dropout_p) ? 0 : 1;
    sum = sum * drop / (1.0f - dropout_p);

    // Now perform softmax within the row
    // Phase 1: Find row maximum
    float local_max = sum;

    // Reduce within warp
    for (int offset = 16; offset > 0; offset /= 2) {
        local_max = fmaxf(local_max, __shfl_down(local_max, offset, 32));
    }

    // First thread in warp writes to shared
    __shared__ float row_max[TILE];
    int warp_id = threadIdx.x / 32;
    int lane_id = threadIdx.x % 32;

    if (lane_id == 0) {
        row_max[warp_id] = local_max;
    }

    __syncthreads();

    // Reduce across warps
    float block_max = row_max[threadIdx.y];
    for (int i = 1; i < (TILE + 31) / 32 && i < TILE; i++) {
        block_max = fmaxf(block_max, row_max[i]);
    }

    // Broadcast max to all threads
    __syncthreads();
    row_max[threadIdx.y] = block_max;
    __syncthreads();

    float max_val = row_max[threadIdx.y];

    // Phase 2: Compute exponentials and sum
    float exp_val = expf(sum - max_val);
    float local_sum = exp_val;

    // Warp reduction for sum
    for (int offset = 16; offset > 0; offset /= 2) {
        local_sum += __shfl_down(local_sum, offset, 32);
    }

    // Shared memory for sum - use atomic for correctness
    __shared__ float row_sum[TILE];

    if (lane_id == 0) {
        row_sum[warp_id] = 0.0f;
    }
    __syncthreads();

    if (lane_id == 0) {
        atomicAdd(&row_sum[warp_id], local_sum);
    }
    __syncthreads();

    // Reduce across warps
    float block_sum = 0.0f;
    for (int i = 0; i < (TILE + 31) / 32 && i < TILE; i++) {
        block_sum += row_sum[i];
    }

    // Broadcast to all threads
    __shared__ float final_sum[TILE];
    final_sum[threadIdx.y] = block_sum;
    __syncthreads();

    // Final softmax
    float softmax_val = exp_val / final_sum[threadIdx.y];

    // Write output
    if (row_start + row_offset < out_features && col_idx < out_features) {
        output[batch_idx * out_features + (row_start + row_offset)] = softmax_val;
    }
}

